function allow() {
  return { decision: "allow", allowed: true, reasonCode: null, nextAction: null };
}
function guardEventDateChange({ commercialStage, humanAuthorized = false }) {
  if (commercialStage === "GANHO" && !humanAuthorized) {
    return {
      decision: "human",
      allowed: false,
      reasonCode: "POST_WIN_DATE_CHANGE_REQUIRES_HUMAN_REVIEW",
      nextAction: "human_required",
    };
  }
  return allow();
}
return {json:guardEventDateChange({
  commercialStage:$json.commercial_stage ?? $json.commercialStage ?? null,
  humanAuthorized:Boolean($json.human_authorized ?? $json.humanAuthorized)
})};

const input=$('Receive Logistics Context').item.json;
const items=Array.isArray(input.checklist)?input.checklist:[];
const blockers=[];
for(const item of items){
  if(item?.critical!==true) continue;
  if(!['done','verified','ready'].includes(String(item.status ?? '').toLowerCase())){
    blockers.push('CHECKLIST_INCOMPLETE:'+String(item.code ?? 'unknown'));
  }
}
for(const blocker of (input.external_blockers ?? [])){
  if(blocker) blockers.push(String(blocker));
}
return {json:{
  critical_checklist_ready:blockers.length===0,
  blockers,
  checklist_snapshot:items
}};

// GENERATED ADAPTER FOR n8n CODE NODE.
// Canonical source: src/functions/f2/readiness.mjs#evaluateModuleReadiness

function result(status, ready, blockers = []) {
  return { status, ready, blockers };
}
function evaluateModuleReadiness(moduleCode, context = {}) {
  switch (moduleCode) {
    case "quote":
      return context.quoteReady
        ? result("ready", true)
        : result("blocked", false, ["QUOTE_NOT_READY"]);
    case "contract":
      return context.contractStatus === "signed"
        ? result("completed", true)
        : result("in_progress", false, ["CONTRACT_NOT_SIGNED"]);
    case "payment":
      return context.paymentVerified === true &&
        ["signal", "full"].includes(context.paymentKind)
        ? result("completed", true)
        : result("in_progress", false, ["SIGNAL_OR_FULL_PAYMENT_NOT_VERIFIED"]);
    case "art":
      return context.artFinalApproved === true
        ? result("completed", true)
        : result("in_progress", false, ["ART_NOT_FINAL"]);
    case "logistics":
      return context.criticalChecklistReady === true && !(context.blockers?.length)
        ? result("ready", true)
        : result("blocked", false, context.blockers?.length ? context.blockers : ["LOGISTICS_NOT_READY"]);
    case "delivery":
      return context.linkSent === true && context.confirmationPolicySatisfied === true
        ? result("completed", true)
        : result("in_progress", false, ["DELIVERY_POLICY_INCOMPLETE"]);
    case "post_sale":
      return context.actionsCompletedOrSkipped === true
        ? result("completed", true)
        : result("in_progress", false, ["POST_SALE_INCOMPLETE"]);
    case "reservation":
      return context.reservationStatus === "confirmed"
        ? result("completed", true)
        : result("in_progress", false, ["RESERVATION_NOT_CONFIRMED"]);
    default:
      return result("blocked", false, ["UNKNOWN_MODULE_CODE:" + moduleCode]);
  }
}
return {json:evaluateModuleReadiness("logistics",{
  criticalChecklistReady:Boolean($json.critical_checklist_ready ?? $json.criticalChecklistReady),
  blockers:$json.blockers ?? []
})};

const readiness=$json;
const input=$('Receive Logistics Context').item.json;
const dateGuard=$('Run F2 Post-win Date Guard').item.json;
const prep=$('Prepare Logistics Readiness').item.json;
const eventId=input.customer_event_id;
const trigger=String(input.trigger_type ?? '');

if(trigger==='date_changed'){
  if(!dateGuard.allowed){
    return {json:{
      status:'human_required',
      operations:[
        {action:'UPDATE_LOGISTICS_RECORD',customer_event_id:eventId,status:'changed'},
        {action:'ENABLE_HUMAN_LOCK',reason_code:dateGuard.reasonCode},
        {action:'CREATE_HUMAN_TASK',customer_event_id:eventId,task_type:'logistics_date_review',reason_code:dateGuard.reasonCode},
        {action:'REQUEST_FACT_REVIEW',customer_event_id:eventId,fact_key:'event_date'}
      ],
      trello_move_allowed:false,
      blockers:[dateGuard.reasonCode]
    }};
  }
  return {json:{
    status:'planned',
    operations:[
      {action:'UPDATE_LOGISTICS_RECORD',customer_event_id:eventId,status:'changed'},
      {action:'REBUILD_LOGISTICS_CHECKLIST',customer_event_id:eventId},
      {action:'UPDATE_LOGISTICS_PROJECTION_CONTENT',customer_event_id:eventId,preserve_existing_structure:true,move_list:false}
    ],
    trello_move_allowed:false,
    blockers:[]
  }};
}

const logisticsStatus=readiness.ready?'ready':'blocked';
const operations=[
  {
    action:'UPSERT_LOGISTICS_RECORD',
    customer_event_id:eventId,
    status:logisticsStatus,
    checklist:prep.checklist_snapshot
  },
  {
    action:'UPSERT_MODULE_STATE',
    customer_event_id:eventId,
    module_code:'logistics',
    status:readiness.status,
    ready:Boolean(readiness.ready),
    blockers:readiness.blockers
  },
  {
    action:'UPDATE_LOGISTICS_PROJECTION_CONTENT',
    customer_event_id:eventId,
    preserve_existing_structure:true,
    move_list:false
  }
];
if(readiness.ready){
  operations.push({action:'EMIT_EVENT',event_type:'logistics_ready',customer_event_id:eventId});
}

return {json:{
  status:readiness.ready?'ready':'blocked',
  readiness,
  operations,
  trello_move_allowed:false,
  blockers:readiness.blockers
}};
